import{_ as s}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as a}from"./chunks/EN.P9aPnFBv.js";import{_ as e}from"./chunks/DIS.DdpTdGGD.js";import{_ as i}from"./chunks/OFF.BrU7kQE-.js";import{_ as t}from"./chunks/M-S-SY8d2.DVL3poO_.js";import{_ as n,o as r,c as l,a3 as c}from"./chunks/framework.g9mfNVRQ.js";const w=JSON.parse('{"title":"xDrip Sync","description":"","frontmatter":{"source_hash":"8ff0f07a91","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"it/use/sync.md","filePath":"it/use/sync.md"}'),p={name:"it/use/sync.md"};function d(m,o,u,z,v,h){return r(),l("div",null,[...o[0]||(o[0]=[c('<div class="admonition xdrip"><p class="admonition-title"><img src="'+s+'" style="zoom:75%;"></p><p> Impostazioni<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_google_circles_communities_grey600_48dp.png" style="width:5%;"> Impostazioni xDrip+ Sync</p></div><div class="warning custom-block"><p class="custom-block-title">Vecchio xDrip Sync</p><p>A luglio 2024 Google ha chiuso la <a href="https://firebase.google.com/docs/cloud-messaging/migrate-v1" target="_blank" rel="noreferrer">Firebase API</a> deprecata che xDrip usava per xDrip Sync.<br> Aggiorna xDrip a una versione successiva al <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2024.07.23" target="_blank" rel="noreferrer">23 luglio 2024</a> per usare il metodo Sync legacy.<br> Si consiglia di aggiornare xDrip all&#39;ultima release.</p></div><div class="warning custom-block"><p class="custom-block-title">Attenzione</p><p>I <a href="https://play.google.com/store/apps/details?id=com.google.android.gms" target="_blank" rel="noreferrer">Google Play services</a> sono indispensabili per usare questa funzione. Assicurati che siano presenti, attivati e non soggetti all&#39;ottimizzazione della batteria.</p></div><p>xDrip offre un meccanismo esclusivo di sincronizzazione in tempo reale tra dispositivi Android, che rende la condivisione di glicemia e trattamenti il più semplice possibile.</p><p>La chiave di sicurezza sottostante può essere personalizzata invece di usare la chiave dell&#39;account Google (non modificabile).</p><div class="admonition xdripitem"><p class="admonition-title">Sincronizza usando la Chiave di Sicurezza <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> La Chiave è usata al posto dell&#39;account Google</p></div><h5 id="handset-group-security-sync-key" tabindex="-1">Chiave di sicurezza del Gruppo per sincronizzazione <a class="header-anchor" href="#handset-group-security-sync-key" aria-label="Permalink to &quot;Chiave di sicurezza del Gruppo per sincronizzazione {#handset-group-security-sync-key}&quot;">​</a></h5><p>All&#39;installazione di xDrip viene creata una chiave unica (sarà diversa se reinstalli xDrip), che deve coincidere su tutti i dispositivi che usano xDrip Sync. Anche se puoi personalizzare questa chiave scegliendone una tua (lettere e numeri), di solito la lascerai come è stata generata.</p><div class="admonition xdripitem"><p class="admonition-title">Chiave di sicurezza del Gruppo per sincronizzazione</p><p> Chiave di gruppo per sincronizzazione telefoni</p></div><h5 id="be-master-for-followers" tabindex="-1">Imposta come Telefono Principale (MASTER) per tel. secondari (FOLLOWER) <a class="header-anchor" href="#be-master-for-followers" aria-label="Permalink to &quot;Imposta come Telefono Principale (MASTER) per tel. secondari (FOLLOWER) {#be-master-for-followers}&quot;">​</a></h5><p>Il dispositivo che riceve i dati glicemici dal sensore sarà il master, tutti gli altri saranno follower.<br> Un solo master può usare la stessa chiave di sicurezza. Se vengono rilevati due master, l&#39;ultimo arrivato verrà disattivato e tornerà follower.</p><div class="admonition xdripitem"><p class="admonition-title">Imposta come Telefono Principale (MASTER) per tel. secondari (FOLLOWER) <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Questo telefono invierà i dati ad apparecchi Secondari</p></div><h5 id="accept-followers-actions" tabindex="-1">Accetta le azioni dei follower <a class="header-anchor" href="#accept-followers-actions" aria-label="Permalink to &quot;Accetta le azioni dei follower {#accept-followers-actions}&quot;">​</a></h5><p>Puoi configurare il telefono master per ricevere e accettare trattamenti e calibrazioni dai follower. Fai estrema attenzione con questa funzione se usi le calibrazioni automatiche. Ricorda anche che l&#39;avvio e l&#39;arresto del sensore possono essere inviati dai follower e accettati dal master.</p><div class="admonition xdripitem"><p class="admonition-title">Accetta le azioni dei follower <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Trattamenti e calibrazioni mandati dei follower saranno accettati</p></div><h5 id="use-xdrip-cloud" tabindex="-1">Usa xDrip Cloud <a class="header-anchor" href="#use-xdrip-cloud" aria-label="Permalink to &quot;Usa xDrip Cloud {#use-xdrip-cloud}&quot;">​</a></h5><p>Dopo che Google ha chiuso a luglio 2024 la <a href="https://firebase.google.com/docs/cloud-messaging/migrate-v1" target="_blank" rel="noreferrer">Firebase API</a> deprecata usata per xDrip Sync, è stato sviluppato un nuovo metodo di condivisione.</p><div class="warning custom-block"><p class="custom-block-title">Deve essere impostato allo stesso modo su tutti i telefoni</p><p>Master e follower. O è attivo su tutti, o è disattivato su tutti.</p></div><div class="admonition xdripitem"><p class="admonition-title">Usa xDrip Cloud <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Usa i nuovi server cloud xDrip+. Master e follower devono avere entrambi questa impostazione selezionata.</p></div><p>Se xDrip consuma troppa batteria quando usa i dati mobili della SIM, puoi provare ad attivare questa opzione.</p><div class="admonition xdripitem"><p class="admonition-title">Risparmia energia <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Riduce l&#39;utilizzo della batteria dei dati di rete con l&#39;elaborazione in batch escludendo dati inutili</p></div><h5 id="whole-house" tabindex="-1">Whole house <a class="header-anchor" href="#whole-house" aria-label="Permalink to &quot;Whole house {#whole-house}&quot;">​</a></h5><p>Basandosi sul progetto <a href="https://github.com/jamorham/wixel-xDrip" target="_blank" rel="noreferrer">Parakeet</a>, più dispositivi <strong>master</strong> possono creare una rete che copre tutta la casa.<br> Se usi sensori Libre puoi usare anche questa funzione: vedi <a href="https://github.com/tzachi-dar/LibreAllHouse" target="_blank" rel="noreferrer">qui</a> come creare la tua rete per tutta la casa.</p><div class="admonition xdripitem"><p class="admonition-title">Whole House <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Partecipa a una rete di casa intera (LibreAllHouse)</p></div><div class="admonition xdripitem"><p class="admonition-title">Libre copertura Casa Intera <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Questo telefono sarà un collector in una rete di copertura casa completa</p></div><h5 id="remote-snoozing" tabindex="-1">Sospensione allarmi a distanza <a class="header-anchor" href="#remote-snoozing" aria-label="Permalink to &quot;Sospensione allarmi a distanza {#remote-snoozing}&quot;">​</a></h5><p>La sospensione a distanza permette di propagare la richiesta di sospensione a tutto il gruppo. Sia il master sia i follower possono sospendere gli allarmi. Usala con cautela.</p><div class="admonition xdripitem"><p class="admonition-title">Invia sospensione allarme a tutti <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Le sospensione allarme avranno effetto su tutti i telefoni del gruppo se questa impostazione è abilitata su ognuno di loro</p></div><div class="admonition xdripitem"><p class="admonition-title">Conferma invio sospensione allarme <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Messaggio di conferma a l&#39;invio di ogni sospensione allarme a distanza</p></div><div class="admonition xdripitem"><p class="admonition-title">Accetta sospensione allarme a distanza <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Consenti a tutti i telefoni di sospendere a distanza gli allarmi su questo telefono</p></div><div class="admonition xdripitem"><p class="admonition-title">Il nome del WiFi deve essere identico <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Accetta solo se il nome della rete WiFi remota inizia con le stesse lettere e somiglia molto a la nostra</p></div><h5 id="local-broadcast" tabindex="-1">Trasmissione Locale <a class="header-anchor" href="#local-broadcast" aria-label="Permalink to &quot;Trasmissione Locale {#local-broadcast}&quot;">​</a></h5><p>Trasmissione Locale invia o accetta sospensioni verso/da altre app (non xDrip) installate sullo stesso telefono, indipendentemente dalla sospensione a distanza tra telefoni xDrip.</p><div class="admonition xdripitem"><p class="admonition-title">Trasmissione Locale <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Invia silenziamento ad altre applicazioni su questo telefono</p></div><div class="admonition xdripitem"><p class="admonition-title">Accetta Trasmissione Locale <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Accetta silenziamenti da altre applicazioni su questo telefono</p></div><h5 id="disable-sync" tabindex="-1">Disattivare la sincronizzazione <a class="header-anchor" href="#disable-sync" aria-label="Permalink to &quot;Disattivare la sincronizzazione {#disable-sync}&quot;">​</a></h5><p>Disattivare tutte le funzioni di sincronizzazione blocca completamente la condivisione. Quando la riattivi potrebbe essere necessario riavviare il telefono.</p><p>Puoi usare questa opzione in caso di malfunzionamento totale di Sync o quando usi un telefono senza Google Play Services.</p><div class="admonition xdripitem"><p class="admonition-title">Disattivare tutte le funzioni di sincronizzazione <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Opzione Modifica Programma Temporanea, si ferma completamente tutta la sincronizzazione. Potrebbe essere necessario riavviare il sistema dopo essere stato riattivato. Usare con cautela!</p></div><h3 id="desert-sync" tabindex="-1">Sincronizzazione nel deserto <a class="header-anchor" href="#desert-sync" aria-label="Permalink to &quot;Sincronizzazione nel deserto {#desert-sync}&quot;">​</a></h3><p>Sincronizzazione nel deserto permette di usare xDrip Sync senza internet né copertura dati del telefono.</p><div class="admonition xdripitem"><p class="admonition-title">Sincronizzazione nel deserto</p><p><img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xxhdpi/desert_sync.png" style="width:5%;"> Follower fuori rete dati</p></div><p>Sincronizzazione nel deserto ti permette di condividere i dati tra il master xDrip e i follower quando internet non è disponibile. Può succedere quando viaggi fuori dalla copertura telefonica o su una intranet locale (senza accesso a internet).</p><p>Attiva la sincronizzazione nel deserto su tutti i dispositivi.</p><div class="admonition xdripitem"><p class="admonition-title">Sincronizzazione nel deserto <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Attivata sincronizzazione locale (non internet)</p></div><p>Se conosci l&#39;indirizzo IP del master (vale per le intranet locali), inseriscilo qui.<br> Trovi l&#39;IP del master nelle impostazioni Android del telefono - Informazioni sul telefono - Indirizzo IP.</p><div class="admonition xdripitem"><p class="admonition-title">Indirizzo IP del Master</p></div><p>Ora mostra il codice QR delle impostazioni del master e scansionalo sui follower con <a href="./copysettings.html#auto-configure">Configurazione automatica</a>.</p><div class="admonition xdripitem"><p class="admonition-title">Mostra Codice QR</p><p>Codice a barre da scansionare per configurare i follower</p></div><p>Se vuoi proteggere la connessione (intranet locali e wifi pubblici) puoi attivare https.</p><div class="admonition xdripitem"><p class="admonition-title">Usa HTTPS <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p>Aggiungi un altro livello di crittografia per reti condivise, per esempio wifi pubblici</p></div><p>Se non hai dati mobili né Wi-Fi, metti il telefono master in modalità hotspot Wi-Fi e connetti i follower tramite tethering. La distanza massima tra i dispositivi sarà limitata. Questo peserà anche molto sulla batteria del master: assicurati di avere a disposizione un power bank di riserva.<br> Quando usi il tethering devi attivare un <a href="./interapp.html#web-service">servizio web</a> sul master. Assicurati che il secret sia identico sul master e sui follower.</p><p>Controlla in Stato del sistema che tutto si connetta correttamente.</p><img src="'+t+'" style="zoom:75%;"><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Ultima modifica 23/11/2026</em></a></p>',56)])])}const S=n(p,[["render",d]]);export{w as __pageData,S as default};
